import { chromium } from 'playwright-core'

const url=process.env.EXO_QA_URL||'http://127.0.0.1:5199'
const cycles=Number(process.env.EXO_QA_CYCLES||12)
const report={url,cycles,checks:[],failures:[],metrics:{},limitations:[]}
const check=(name,pass,detail={})=>{report.checks.push({name,pass,...detail});if(!pass)report.failures.push(name)}
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']})
try{
 const page=await browser.newPage({viewport:{width:1440,height:900}})
 const errors=[];page.on('pageerror',e=>errors.push(e.message))
 await page.goto(url+'/?desktop=1&testSession=handoff-hover-lifecycle',{waitUntil:'domcontentloaded'})
 await page.getByRole('button',{name:'Browse garments'}).waitFor()
 await page.getByRole('navigation',{name:'Library categories'}).getByRole('button',{name:'Garment',exact:true}).click()
 const tile=page.locator('.asset-template[data-library-hover-id^="Garment:"]').first()
 await tile.scrollIntoViewIfNeeded()
 const id=await tile.getAttribute('data-library-hover-id')
 const popup=page.locator(`[data-library-preview="${id}"]`)
 const count=()=>page.evaluate(()=>({portals:document.querySelectorAll('.exo-library-asset-hover').length,canvases:document.querySelectorAll('.exo-library-asset-hover canvas').length,totalCanvas:document.querySelectorAll('canvas').length}))
 const baseline=await count(),samples=[],began=Date.now()
 for(let i=0;i<cycles;i++){
   await tile.hover();await popup.waitFor({state:'visible',timeout:8000})
   const opened=await count()
   await page.mouse.move(1420,40)
   await popup.waitFor({state:'hidden',timeout:8000})
   const closed=await count()
   samples.push({cycle:i+1,opened,closed})
   check(`hover cycle ${i+1}`,opened.portals===1&&opened.canvases===1&&closed.portals===0&&closed.canvases===0,{opened,closed})
 }
 report.metrics={baseline,elapsedMs:Date.now()-began,peakPortals:Math.max(...samples.map(s=>s.opened.portals)),peakPreviewCanvases:Math.max(...samples.map(s=>s.opened.canvases)),closedTotalCanvasRange:[Math.min(...samples.map(s=>s.closed.totalCanvas)),Math.max(...samples.map(s=>s.closed.totalCanvas))],samples}
 await tile.focus();await popup.waitFor({state:'visible'})
 await tile.press('Tab')
 check('Tab enters popup and keeps it mounted',await popup.isVisible()&&await popup.getByRole('button',{name:'Style lines',exact:true}).evaluate(el=>document.activeElement===el))
 await page.keyboard.press('Shift+Tab')
 check('Shift+Tab returns focus to tile',await tile.evaluate(el=>document.activeElement===el))
 await tile.press('Tab')
 await page.keyboard.press('Escape')
 check('Escape dismisses and returns focus',await popup.isHidden()&&await tile.evaluate(el=>document.activeElement===el))
 check('desktop JavaScript errors',errors.length===0,{errors})
 await page.close()
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true})
 const mobileErrors=[];mobile.on('pageerror',e=>mobileErrors.push(e.message))
 await mobile.goto(url+'/?desktop=1&testSession=handoff-hover-mobile',{waitUntil:'domcontentloaded'})
 await mobile.getByRole('button',{name:'Browse garments'}).waitFor()
 await mobile.getByRole('navigation',{name:'Library categories'}).getByRole('button',{name:'Garment',exact:true}).click()
 const mobileTile=mobile.locator('.asset-template[data-library-hover-id^="Garment:"]').first()
 await mobileTile.scrollIntoViewIfNeeded()
 const mobileId=await mobileTile.getAttribute('data-library-hover-id')
 const hint=mobileTile.locator('[data-library-preview-touch]')
 check('mobile tap affordance visible',await hint.isVisible())
 await hint.tap()
 const mobilePopup=mobile.locator(`[data-library-preview="${mobileId}"]`)
 await mobilePopup.waitFor({state:'visible'})
 check('mobile tap opens a single preview canvas',await mobile.locator('.exo-library-asset-hover').count()===1&&await mobilePopup.locator('canvas').count()===1)
 await mobile.keyboard.press('Escape')
 check('mobile Escape closes preview',await mobilePopup.isHidden())
 check('mobile JavaScript errors',mobileErrors.length===0,{errors:mobileErrors})
 await mobile.close()
 report.limitations.push('DOM canvas/portal counts measure detached elements, not GPU allocations or retained WebGL memory.')
}catch(error){report.failures.push('uncaught '+error.message);report.error=error.stack}finally{await browser.close();console.log(JSON.stringify(report,null,2));if(report.failures.length)process.exitCode=1}
